
create proc [dbo].[TransItem]


@TRANS int,
@DateBegin date,
@DateEnd date
as
     DECLARE @VisbleThreeUnit BIT=1 
SELECT @VisbleThreeUnit= VisbleThreeUnit FROM ZZproperties
IF @VisbleThreeUnit=1
begin
 
IF @TRANS=0     SELECT  pur_Invoice.CostCenter, CASE WHEN [TypePaied] = 1 THEN 'B-Credit' WHEN [TypePaied] = 2 THEN 'B-Net' ELSE 'B-Cash' END AS TypePaied, Pur_Details.des,ROUND((isnull(Pur_Details.qu,0)+isnull(Pur_Details.bones,0))*Item.CountMetr, 4) AS CountMetr,  Pur_Details.id_pur AS bill, Pur_Details.id_item, Pur_Details.LOT,case when isnull(Pur_Details.tax,0) =0 then 0 else round(convert(float,Pur_Details.total_item*Pur_Details.tax/100),2) end  AS tax,ROUND(Pur_Details.qu, 4) AS qu, ROUND(convert(float,Pur_Details.pr),4) as pr, ROUND(convert(float,Pur_Details.Discount),4) as Discount, Pur_Details.bones, ROUND(convert(float,Pur_Details.total_item),4) as total_item, Pur_Details.unit, Item.ARname, Item.InternationalCode,Item.ShortName, LTRIM(RTRIM(STR(CurrentBalance0))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS balance, Pur_Invoice.user_name,Pur_Invoice.delegateName,Pur_Invoice.id_bill,isnull(Pur_Invoice.commission ,0) as commission,round(convert(float,((isnull(Pur_Invoice.commission,0) * isnull(Pur_Details.total_item ,0))/100)),2) as total_commission, Pur_Invoice.pdate, cust.Aname AS Cust_Name1, Z_Stores.aname AS StoreName, Z_TypeItem1.aname AS TypeItem1, Z_TypeItem2.aname AS TypeItem2, Z_TypeItem3.aname AS TypeItem3, CASE WHEN [unit] = 0 THEN isnull(Z_BigUnit.aname, 'U-Big') WHEN [unit] = 1 THEN isnull(Z_MiddellUnit.aname, 'U-Middell') ELSE isnull(Z_SmallUnit.aname, 'U-Small') END AS UnitName, Z_TypeItem4.aname AS TypeItem4, Z_TypeItem5.aname AS TypeItem5, Z_TypeItem6.aname AS TypeItem6, Z_TypeItem7.aname AS TypeItem7,Item.Minimum, LTRIM(RTRIM(STR(isnull(CurrentBalance0,0)- isnull(Item.Minimum,0)))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS OverMinimum FROM         Pur_Details INNER JOIN Item ON Pur_Details.id_item = Item.id_item INNER JOIN Pur_Invoice ON Pur_Details.id_pur = Pur_Invoice.id_pur INNER JOIN cust ON Pur_Invoice.id_cust = cust.id_cust left JOIN Z_Stores ON Pur_Details.id_store = Z_Stores.id LEFT OUTER JOIN Z_TypeItem4 ON Item.IdTypeItem4 = Z_TypeItem4.id LEFT OUTER JOIN Z_TypeItem5 ON Item.IdTypeItem5 = Z_TypeItem5.id LEFT OUTER JOIN Z_TypeItem6 ON Item.IdTypeItem6 = Z_TypeItem6.id LEFT OUTER JOIN Z_TypeItem7 ON Item.IdTypeItem7 = Z_TypeItem7.id LEFT OUTER JOIN Z_TypeItem1 ON Item.IdTypeItem1 = Z_TypeItem1.id LEFT OUTER JOIN Z_TypeItem2 ON Item.IdTypeItem2 = Z_TypeItem2.id LEFT OUTER JOIN Z_TypeItem3 ON Item.IdTypeItem3 = Z_TypeItem3.id LEFT OUTER JOIN Z_BigUnit ON Item.IdBigUnit = Z_BigUnit.id LEFT OUTER JOIN Z_MiddellUnit ON Item.IdMiddellUnit = Z_MiddellUnit.id LEFT OUTER JOIN Z_SmallUnit ON Item.IdSmallUnit = Z_SmallUnit.id  WHERE CONVERT(DATE,pur_Invoice.pdate) between @DateBegin and @DateEnd  ORDER BY bill

IF @TRANS=1     SELECT  Rpur_Invoice.CostCenter, CASE WHEN [TypePaied] = 1 THEN 'B-Credit' WHEN [TypePaied] = 2 THEN 'B-Net' ELSE 'B-Cash' END AS TypePaied, ROUND((isnull(RPur_Details.qu,0)+isnull(RPur_Details.bones,0))*Item.CountMetr, 4) AS CountMetr,  Rpur_Details.id_Rpur AS bill, Rpur_Details.id_item,  ROUND(Rpur_Details.qu, 4) AS qu, ROUND(convert(float,Rpur_Details.pr),4) as pr, ROUND(convert(float,Rpur_Details.Discount),4) as Discount, Rpur_Details.bones, ROUND(convert(float,Rpur_Details.total_item),4) as total_item, Rpur_Details.unit, Item.ARname, Item.commission,Item.InternationalCode,Item.ShortName, LTRIM(RTRIM(STR(CurrentBalance0))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS balance, Rpur_Invoice.user_name,RPur_Invoice.id_bill, Rpur_Invoice.pdate, cust.Aname AS Cust_Name1, Z_Stores.aname AS StoreName, Z_TypeItem1.aname AS TypeItem1, Z_TypeItem2.aname AS TypeItem2, Z_TypeItem3.aname AS TypeItem3, CASE WHEN [unit] = 0 THEN isnull(Z_BigUnit.aname, 'U-Big') WHEN [unit] = 1 THEN isnull(Z_MiddellUnit.aname, 'U-Middell') ELSE isnull(Z_SmallUnit.aname, 'U-Small') END AS UnitName, Z_TypeItem4.aname AS TypeItem4, Z_TypeItem5.aname AS TypeItem5, Z_TypeItem6.aname AS TypeItem6, Z_TypeItem7.aname AS TypeItem7 ,Item.Minimum, LTRIM(RTRIM(STR(isnull(CurrentBalance0,0)- isnull(Item.Minimum,0)))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS OverMinimum FROM         Rpur_Details INNER JOIN Item ON Rpur_Details.id_item = Item.id_item INNER JOIN Rpur_Invoice ON Rpur_Details.id_Rpur = Rpur_Invoice.id_Rpur INNER JOIN cust ON Rpur_Invoice.id_cust = cust.id_cust left JOIN Z_Stores ON Rpur_Invoice.id_store = Z_Stores.id LEFT OUTER JOIN Z_TypeItem4 ON Item.IdTypeItem4 = Z_TypeItem4.id LEFT OUTER JOIN Z_TypeItem5 ON Item.IdTypeItem5 = Z_TypeItem5.id LEFT OUTER JOIN Z_TypeItem6 ON Item.IdTypeItem6 = Z_TypeItem6.id LEFT OUTER JOIN Z_TypeItem7 ON Item.IdTypeItem7 = Z_TypeItem7.id LEFT OUTER JOIN Z_TypeItem1 ON Item.IdTypeItem1 = Z_TypeItem1.id LEFT OUTER JOIN Z_TypeItem2 ON Item.IdTypeItem2 = Z_TypeItem2.id LEFT OUTER JOIN Z_TypeItem3 ON Item.IdTypeItem3 = Z_TypeItem3.id LEFT OUTER JOIN Z_BigUnit ON Item.IdBigUnit = Z_BigUnit.id LEFT OUTER JOIN Z_MiddellUnit ON Item.IdMiddellUnit = Z_MiddellUnit.id LEFT OUTER JOIN Z_SmallUnit ON Item.IdSmallUnit = Z_SmallUnit.id  WHERE CONVERT(DATE,Rpur_Invoice.pdate) between @DateBegin and @DateEnd ORDER BY bill

IF @TRANS=2     SELECT  sal_Invoice.CostCenter,CASE WHEN [TypePaied] = 1 THEN 'B-Credit' WHEN [TypePaied] = 2 THEN 'B-Net' ELSE 'B-Cash' END AS TypePaied,sal_Details.QuSend, sal_Details.des,ROUND((isnull(sal_Details.qu,0)+isnull(sal_Details.bones,0))*Item.CountMetr, 4) AS CountMetr,  Convert(decimal(18,2),((Sal_Details.profit/(Sal_Details.total_item+(Sal_Details.total_item * isnull(Sal_Details.tax,0) / 100)+.0001))*100)) as  PercentProfit, Sal_Details.id_sal AS bill, Sal_Details.id_item, Sal_Details.LOT,case when isnull(Sal_Details.tax,0) =0 then 0 else round(convert(float,Sal_Details.total_item*Sal_Details.tax/100),2) end  AS tax, ROUND(Sal_Details.qu, 4) AS qu, ROUND(convert(float,Sal_Details.pr),4) as pr, ROUND(convert(float,Sal_Details.Discount),4) as Discount, Sal_Details.bones, ROUND(convert(float,Sal_Details.total_item),4) as total_item,ROUND(convert(float,Sal_Details.total_item*Item.commission/100),2) as total_commission, Sal_Details.unit, round(convert(float,Sal_Details.profit),4)AS profit,  ROUND(ROUND(convert(float,Sal_Details.total_item),2) - ROUND(convert(float,Sal_Details.profit),2), 2) AS cost, Item.ARname,Item.commission, Item.InternationalCode, Item.ShortName,LTRIM(RTRIM(STR(CurrentBalance0))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS balance, Sal_Invoice.user_name,sal_Invoice.id_bill, Sal_Invoice.delegateName, Sal_Invoice.pdate, cust.Aname AS Cust_Name1,cust.way,cust.Mobile,cust.Address, Z_Stores.aname AS StoreName, Z_TypeItem1.aname AS TypeItem1, Z_TypeItem2.aname AS TypeItem2, Z_TypeItem3.aname AS TypeItem3, CASE WHEN [unit] = 0 THEN isnull(Z_BigUnit.aname, 'U-Big') WHEN [unit] = 1 THEN isnull(Z_MiddellUnit.aname, 'U-Middell') ELSE isnull(Z_SmallUnit.aname, 'U-Small') END AS UnitName, Z_TypeItem4.aname AS TypeItem4, Z_TypeItem5.aname AS TypeItem5, Z_TypeItem6.aname AS TypeItem6, Z_TypeItem7.aname AS TypeItem7,Item.Minimum, LTRIM(RTRIM(STR(isnull(CurrentBalance0,0)- isnull(Item.Minimum,0)))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS OverMinimum FROM         Sal_Details INNER JOIN Item ON Sal_Details.id_item = Item.id_item INNER JOIN Sal_Invoice ON Sal_Details.id_sal = Sal_Invoice.id_sal INNER JOIN cust ON Sal_Invoice.id_cust = cust.id_cust left JOIN Z_Stores ON Sal_Details.id_store = Z_Stores.id LEFT OUTER JOIN Z_TypeItem4 ON Item.IdTypeItem4 = Z_TypeItem4.id LEFT OUTER JOIN Z_TypeItem5 ON Item.IdTypeItem5 = Z_TypeItem5.id LEFT OUTER JOIN Z_TypeItem6 ON Item.IdTypeItem6 = Z_TypeItem6.id LEFT OUTER JOIN Z_TypeItem7 ON Item.IdTypeItem7 = Z_TypeItem7.id LEFT OUTER JOIN Z_TypeItem1 ON Item.IdTypeItem1 = Z_TypeItem1.id LEFT OUTER JOIN Z_TypeItem2 ON Item.IdTypeItem2 = Z_TypeItem2.id LEFT OUTER JOIN Z_TypeItem3 ON Item.IdTypeItem3 = Z_TypeItem3.id LEFT OUTER JOIN Z_BigUnit ON Item.IdBigUnit = Z_BigUnit.id LEFT OUTER JOIN Z_MiddellUnit ON Item.IdMiddellUnit = Z_MiddellUnit.id LEFT OUTER JOIN Z_SmallUnit ON Item.IdSmallUnit = Z_SmallUnit.id WHERE CONVERT(DATE,sal_Invoice.pdate) between @DateBegin and @DateEnd ORDER BY bill

IF @TRANS=3     SELECT  Rsal_Invoice.CostCenter, CASE WHEN [TypePaied] = 1 THEN 'B-Credit' WHEN [TypePaied] = 2 THEN 'B-Net' ELSE 'B-Cash' END AS TypePaied, Rsal_Invoice.delegateName, ROUND(ROUND(convert(float,RSal_Details.total_item),2) + ROUND(convert(float,RSal_Details.profit),2), 2) AS cost,ROUND((isnull(Rsal_Details.qu,0)+isnull(Rsal_Details.bones,0))*Item.CountMetr, 4) AS CountMetr,  ROUND(convert(float,Rsal_details.total_item*Item.commission/100),2) as total_commission,Rsal_details.id_RSal AS bill, Rsal_details.id_item, ROUND(convert(float,Rsal_details.qu), 4) AS qu,ROUND(convert(float,Rsal_details.Profit ), 4) AS profit, ROUND(convert(float,Rsal_details.pr),4) as pr, ROUND(convert(float,Rsal_details.Discount),4) as Discount, Rsal_details.bones, ROUND(convert(float,Rsal_details.total_item),4) as total_item, Rsal_details.unit, Item.ARname,Item.commission, Item.InternationalCode,Item.ShortName, LTRIM(RTRIM(STR(CurrentBalance0))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS balance, Rsal_invoice.user_name,Rsal_Invoice.id_bill, Rsal_invoice.pdate, cust.Aname AS Cust_Name1,cust.way,cust.Mobile,cust.Address, Z_Stores.aname AS StoreName, Z_TypeItem1.aname AS TypeItem1, Z_TypeItem2.aname AS TypeItem2, Z_TypeItem3.aname AS TypeItem3, CASE WHEN [unit] = 0 THEN isnull(Z_BigUnit.aname, 'U-Big') WHEN [unit] = 1 THEN isnull(Z_MiddellUnit.aname, 'U-Middell') ELSE isnull(Z_SmallUnit.aname, 'U-Small') END AS UnitName, Z_TypeItem4.aname AS TypeItem4, Z_TypeItem5.aname AS TypeItem5, Z_TypeItem6.aname AS TypeItem6, Z_TypeItem7.aname AS TypeItem7,Item.Minimum, LTRIM(RTRIM(STR(isnull(CurrentBalance0,0)- isnull(Item.Minimum,0)))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS OverMinimum FROM         Rsal_details INNER JOIN Item ON Rsal_details.id_item = Item.id_item INNER JOIN Rsal_invoice ON Rsal_details.id_RSal = Rsal_invoice.id_Rsal INNER JOIN cust ON Rsal_invoice.id_cust = cust.id_cust left JOIN Z_Stores ON Rsal_invoice.id_store = Z_Stores.id LEFT OUTER JOIN Z_TypeItem4 ON Item.IdTypeItem4 = Z_TypeItem4.id LEFT OUTER JOIN Z_TypeItem5 ON Item.IdTypeItem5 = Z_TypeItem5.id LEFT OUTER JOIN Z_TypeItem6 ON Item.IdTypeItem6 = Z_TypeItem6.id LEFT OUTER JOIN Z_TypeItem7 ON Item.IdTypeItem7 = Z_TypeItem7.id LEFT OUTER JOIN Z_TypeItem1 ON Item.IdTypeItem1 = Z_TypeItem1.id LEFT OUTER JOIN Z_TypeItem2 ON Item.IdTypeItem2 = Z_TypeItem2.id LEFT OUTER JOIN Z_TypeItem3 ON Item.IdTypeItem3 = Z_TypeItem3.id LEFT OUTER JOIN Z_BigUnit ON Item.IdBigUnit = Z_BigUnit.id LEFT OUTER JOIN Z_MiddellUnit ON Item.IdMiddellUnit = Z_MiddellUnit.id LEFT OUTER JOIN Z_SmallUnit ON Item.IdSmallUnit = Z_SmallUnit.id WHERE CONVERT(DATE,RSAL_Invoice.pdate) between @DateBegin and @DateEnd ORDER BY bill

IF @TRANS=4     SELECT  ItemListPur.id_order as bill,  ItemListPur.id_item, ROUND(convert(float,ItemListPur.qu), 4) AS qu, ROUND(convert(float,ItemListPur.pr),4) as pr, ROUND(convert(float,ItemListPur.Discount),4) as Discount , ROUND(convert(float,ItemListPur.qu*ItemListPur.pr),4) as total_item,ItemListPur.unit, Item.ARname,Item.commission,Item.InternationalCode,Item.ShortName,LTRIM(RTRIM(STR(CurrentBalance0))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS balance, ItemListPur.pdate, cust.Aname AS Cust_Name1,cust.way,cust.Mobile,cust.Address, Z_TypeItem1.aname AS TypeItem1, Z_TypeItem2.aname AS TypeItem2, Z_TypeItem3.aname AS TypeItem3, CASE WHEN [unit] = 0 THEN isnull(Z_BigUnit.aname, 'U-Big') WHEN [unit] = 1 THEN isnull(Z_MiddellUnit.aname, 'U-Middell') ELSE isnull(Z_SmallUnit.aname, 'U-Small') END AS UnitName, Z_TypeItem4.aname AS TypeItem4, Z_TypeItem5.aname AS TypeItem5, Z_TypeItem6.aname AS TypeItem6, Z_TypeItem7.aname AS TypeItem7,Item.Minimum, LTRIM(RTRIM(STR(isnull(CurrentBalance0,0)- isnull(Item.Minimum,0)))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS OverMinimum FROM         ItemListPur INNER JOIN Item ON ItemListPur.id_item = Item.id_item  INNER JOIN cust ON ItemListPur.id_cust = cust.id_cust  LEFT OUTER JOIN Z_TypeItem4 ON Item.IdTypeItem4 = Z_TypeItem4.id LEFT OUTER JOIN Z_TypeItem5 ON Item.IdTypeItem5 = Z_TypeItem5.id LEFT OUTER JOIN Z_TypeItem6 ON Item.IdTypeItem6 = Z_TypeItem6.id LEFT OUTER JOIN Z_TypeItem7 ON Item.IdTypeItem7 = Z_TypeItem7.id LEFT OUTER JOIN Z_TypeItem1 ON Item.IdTypeItem1 = Z_TypeItem1.id LEFT OUTER JOIN Z_TypeItem2 ON Item.IdTypeItem2 = Z_TypeItem2.id LEFT OUTER JOIN Z_TypeItem3 ON Item.IdTypeItem3 = Z_TypeItem3.id LEFT OUTER JOIN Z_BigUnit ON Item.IdBigUnit = Z_BigUnit.id LEFT OUTER JOIN Z_MiddellUnit ON Item.IdMiddellUnit = Z_MiddellUnit.id LEFT OUTER JOIN Z_SmallUnit ON Item.IdSmallUnit = Z_SmallUnit.id WHERE CONVERT(DATE,ItemListPur.pdate) between @DateBegin and @DateEnd ORDER BY bill
IF @TRANS=5     SELECT  ItemListPrice.id_order as bill,  ItemListPrice.id_item, ROUND(convert(float,ItemListPrice.qu), 4) AS qu, ROUND(convert(float,ItemListPrice.pr),4) as pr, ROUND(convert(float,ItemListPrice.Discount),4) as Discount , ROUND(convert(float,ItemListPrice.qu*ItemListPrice.pr),4) as total_item,ItemListPrice.unit, Item.ARname,Item.commission,Item.InternationalCode,Item.ShortName,LTRIM(RTRIM(STR(CurrentBalance0))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS balance, ItemListPrice.pdate, cust.Aname AS Cust_Name1,cust.way,cust.Mobile,cust.Address, Z_TypeItem1.aname AS TypeItem1, Z_TypeItem2.aname AS TypeItem2, Z_TypeItem3.aname AS TypeItem3, CASE WHEN [unit] = 0 THEN isnull(Z_BigUnit.aname, 'U-Big') WHEN [unit] = 1 THEN isnull(Z_MiddellUnit.aname, 'U-Middell') ELSE isnull(Z_SmallUnit.aname, 'U-Small') END AS UnitName, Z_TypeItem4.aname AS TypeItem4, Z_TypeItem5.aname AS TypeItem5, Z_TypeItem6.aname AS TypeItem6, Z_TypeItem7.aname AS TypeItem7,Item.Minimum, LTRIM(RTRIM(STR(isnull(CurrentBalance0,0)- isnull(Item.Minimum,0)))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS OverMinimum FROM         ItemListPrice INNER JOIN Item ON ItemListPrice.id_item = Item.id_item  INNER JOIN cust ON ItemListPrice.id_cust = cust.id_cust  LEFT OUTER JOIN Z_TypeItem4 ON Item.IdTypeItem4 = Z_TypeItem4.id LEFT OUTER JOIN Z_TypeItem5 ON Item.IdTypeItem5 = Z_TypeItem5.id LEFT OUTER JOIN Z_TypeItem6 ON Item.IdTypeItem6 = Z_TypeItem6.id LEFT OUTER JOIN Z_TypeItem7 ON Item.IdTypeItem7 = Z_TypeItem7.id LEFT OUTER JOIN Z_TypeItem1 ON Item.IdTypeItem1 = Z_TypeItem1.id LEFT OUTER JOIN Z_TypeItem2 ON Item.IdTypeItem2 = Z_TypeItem2.id LEFT OUTER JOIN Z_TypeItem3 ON Item.IdTypeItem3 = Z_TypeItem3.id LEFT OUTER JOIN Z_BigUnit ON Item.IdBigUnit = Z_BigUnit.id LEFT OUTER JOIN Z_MiddellUnit ON Item.IdMiddellUnit = Z_MiddellUnit.id LEFT OUTER JOIN Z_SmallUnit ON Item.IdSmallUnit = Z_SmallUnit.id WHERE isnull(ItemListPrice.IsClose,0)=0 and  CONVERT(DATE,ItemListPrice.pdate) between @DateBegin and @DateEnd ORDER BY bill


 end
else
begin
IF @TRANS=0     SELECT   pur_Invoice.CostCenter,Pur_Details.des,ROUND((isnull(Pur_Details.qu,0)+isnull(Pur_Details.bones,0))*Item.CountMetr, 4) AS CountMetr,  Pur_Details.id_pur AS bill, Pur_Details.id_item, Pur_Details.LOT,case when isnull(Pur_Details.tax,0) =0 then 0 else round(convert(float,Pur_Details.total_item*Pur_Details.tax/100),2) end  AS tax,ROUND(Pur_Details.qu, 4) AS qu, ROUND(convert(float,Pur_Details.pr),4) as pr, ROUND(convert(float,Pur_Details.Discount),4) as Discount, Pur_Details.bones, ROUND(convert(float,Pur_Details.total_item),4) as total_item, Pur_Details.unit, Item.ARname, Item.InternationalCode,Item.ShortName, Round(convert(float,isnull(Item.net_balance,0)),2) AS balance, Pur_Invoice.user_name,Pur_Invoice.delegateName,Pur_Invoice.id_bill,isnull(Pur_Invoice.commission ,0) as commission,round(convert(float,((isnull(Pur_Invoice.commission,0) * isnull(Pur_Details.total_item ,0))/100)),2) as total_commission, Pur_Invoice.pdate, cust.Aname AS Cust_Name1,cust.way,cust.Mobile,cust.Address, Z_Stores.aname AS StoreName, Z_TypeItem1.aname AS TypeItem1, Z_TypeItem2.aname AS TypeItem2, Z_TypeItem3.aname AS TypeItem3, CASE WHEN [unit] = 0 THEN isnull(Z_BigUnit.aname, 'U-Big') WHEN [unit] = 1 THEN isnull(Z_MiddellUnit.aname, 'U-Middell') ELSE isnull(Z_SmallUnit.aname, 'U-Small') END AS UnitName, Z_TypeItem4.aname AS TypeItem4, Z_TypeItem5.aname AS TypeItem5, Z_TypeItem6.aname AS TypeItem6, Z_TypeItem7.aname AS TypeItem7,Item.Minimum, Round(convert(float,isnull(Item.net_balance,0) - isnull(Item.Minimum,0)),2) AS OverMinimum FROM         Pur_Details INNER JOIN Item ON Pur_Details.id_item = Item.id_item INNER JOIN Pur_Invoice ON Pur_Details.id_pur = Pur_Invoice.id_pur INNER JOIN cust ON Pur_Invoice.id_cust = cust.id_cust left JOIN Z_Stores ON Pur_Details.id_store = Z_Stores.id LEFT OUTER JOIN Z_TypeItem4 ON Item.IdTypeItem4 = Z_TypeItem4.id LEFT OUTER JOIN Z_TypeItem5 ON Item.IdTypeItem5 = Z_TypeItem5.id LEFT OUTER JOIN Z_TypeItem6 ON Item.IdTypeItem6 = Z_TypeItem6.id LEFT OUTER JOIN Z_TypeItem7 ON Item.IdTypeItem7 = Z_TypeItem7.id LEFT OUTER JOIN Z_TypeItem1 ON Item.IdTypeItem1 = Z_TypeItem1.id LEFT OUTER JOIN Z_TypeItem2 ON Item.IdTypeItem2 = Z_TypeItem2.id LEFT OUTER JOIN Z_TypeItem3 ON Item.IdTypeItem3 = Z_TypeItem3.id LEFT OUTER JOIN Z_BigUnit ON Item.IdBigUnit = Z_BigUnit.id LEFT OUTER JOIN Z_MiddellUnit ON Item.IdMiddellUnit = Z_MiddellUnit.id LEFT OUTER JOIN Z_SmallUnit ON Item.IdSmallUnit = Z_SmallUnit.id  WHERE CONVERT(DATE,pur_Invoice.pdate) between @DateBegin and @DateEnd  ORDER BY bill

IF @TRANS=1     SELECT   Rpur_Invoice.CostCenter,ROUND((isnull(RPur_Details.qu,0)+isnull(RPur_Details.bones,0))*Item.CountMetr, 4) AS CountMetr,  Rpur_Details.id_Rpur AS bill, Rpur_Details.id_item,  ROUND(Rpur_Details.qu, 4) AS qu, ROUND(convert(float,Rpur_Details.pr),4) as pr, ROUND(convert(float,Rpur_Details.Discount),4) as Discount, Rpur_Details.bones, ROUND(convert(float,Rpur_Details.total_item),4) as total_item, Rpur_Details.unit, Item.ARname, Item.InternationalCode,Item.ShortName, Round(convert(float,isnull(Item.net_balance,0)),2) AS balance, Rpur_Invoice.user_name,RPur_Invoice.id_bill, Rpur_Invoice.pdate, cust.Aname AS Cust_Name1,cust.way,cust.Mobile,cust.Address, Z_Stores.aname AS StoreName, Z_TypeItem1.aname AS TypeItem1, Z_TypeItem2.aname AS TypeItem2, Z_TypeItem3.aname AS TypeItem3, CASE WHEN [unit] = 0 THEN isnull(Z_BigUnit.aname, 'U-Big') WHEN [unit] = 1 THEN isnull(Z_MiddellUnit.aname, 'U-Middell') ELSE isnull(Z_SmallUnit.aname, 'U-Small') END AS UnitName, Z_TypeItem4.aname AS TypeItem4, Z_TypeItem5.aname AS TypeItem5, Z_TypeItem6.aname AS TypeItem6, Z_TypeItem7.aname AS TypeItem7 ,Item.Minimum, Round(convert(float,isnull(Item.net_balance,0) - isnull(Item.Minimum,0)),2) AS OverMinimum FROM         Rpur_Details INNER JOIN Item ON Rpur_Details.id_item = Item.id_item INNER JOIN Rpur_Invoice ON Rpur_Details.id_Rpur = Rpur_Invoice.id_Rpur INNER JOIN cust ON Rpur_Invoice.id_cust = cust.id_cust left JOIN Z_Stores ON Rpur_Invoice.id_store = Z_Stores.id LEFT OUTER JOIN Z_TypeItem4 ON Item.IdTypeItem4 = Z_TypeItem4.id LEFT OUTER JOIN Z_TypeItem5 ON Item.IdTypeItem5 = Z_TypeItem5.id LEFT OUTER JOIN Z_TypeItem6 ON Item.IdTypeItem6 = Z_TypeItem6.id LEFT OUTER JOIN Z_TypeItem7 ON Item.IdTypeItem7 = Z_TypeItem7.id LEFT OUTER JOIN Z_TypeItem1 ON Item.IdTypeItem1 = Z_TypeItem1.id LEFT OUTER JOIN Z_TypeItem2 ON Item.IdTypeItem2 = Z_TypeItem2.id LEFT OUTER JOIN Z_TypeItem3 ON Item.IdTypeItem3 = Z_TypeItem3.id LEFT OUTER JOIN Z_BigUnit ON Item.IdBigUnit = Z_BigUnit.id LEFT OUTER JOIN Z_MiddellUnit ON Item.IdMiddellUnit = Z_MiddellUnit.id LEFT OUTER JOIN Z_SmallUnit ON Item.IdSmallUnit = Z_SmallUnit.id  WHERE CONVERT(DATE,Rpur_Invoice.pdate) between @DateBegin and @DateEnd ORDER BY bill

IF @TRANS=2     SELECT   sal_Invoice.CostCenter,sal_Details.QuSend,sal_Details.des,ROUND((isnull(Sal_Details.qu,0)+isnull(Sal_Details.bones,0))*Item.CountMetr, 4) AS CountMetr, Convert(decimal(18,2),((Sal_Details.profit/(Sal_Details.total_item+(Sal_Details.total_item * isnull(Sal_Details.tax,0) / 100)+.0001))*100)) as  PercentProfit, ROUND(convert(float,Sal_Details.total_item*Item.commission/100),2) as total_commission, Sal_Details.id_sal AS bill, Sal_Details.id_item, Sal_Details.LOT,case when isnull(Sal_Details.tax,0) =0 then 0 else round(convert(float,Sal_Details.total_item*Sal_Details.tax/100),2) end  AS tax, ROUND(Sal_Details.qu, 4) AS qu, ROUND(convert(float,Sal_Details.pr),4) as pr, ROUND(convert(float,Sal_Details.Discount),4) as Discount, Sal_Details.bones, ROUND(convert(float,Sal_Details.total_item),4) as total_item, Sal_Details.unit, round(convert(float,Sal_Details.profit),4)AS profit, ROUND(ROUND(convert(float,Sal_Details.total_item),2) - ROUND(convert(float,Sal_Details.profit),2), 2) AS cost, Item.ARname,Item.commission, Item.InternationalCode,Item.ShortName, Round(convert(float,isnull(Item.net_balance,0)),2) AS balance, Sal_Invoice.user_name,sal_Invoice.id_bill, Sal_Invoice.delegateName, Sal_Invoice.pdate, cust.Aname AS Cust_Name1,cust.way,cust.Mobile,cust.Address, Z_Stores.aname AS StoreName, Z_TypeItem1.aname AS TypeItem1, Z_TypeItem2.aname AS TypeItem2, Z_TypeItem3.aname AS TypeItem3, CASE WHEN [unit] = 0 THEN isnull(Z_BigUnit.aname, 'U-Big') WHEN [unit] = 1 THEN isnull(Z_MiddellUnit.aname, 'U-Middell') ELSE isnull(Z_SmallUnit.aname, 'U-Small') END AS UnitName, Z_TypeItem4.aname AS TypeItem4, Z_TypeItem5.aname AS TypeItem5, Z_TypeItem6.aname AS TypeItem6, Z_TypeItem7.aname AS TypeItem7,Item.Minimum, Round(convert(float,isnull(Item.net_balance,0) - isnull(Item.Minimum,0)),2) AS OverMinimum FROM         Sal_Details INNER JOIN Item ON Sal_Details.id_item = Item.id_item INNER JOIN Sal_Invoice ON Sal_Details.id_sal = Sal_Invoice.id_sal INNER JOIN cust ON Sal_Invoice.id_cust = cust.id_cust left JOIN Z_Stores ON Sal_Details.id_store = Z_Stores.id LEFT OUTER JOIN Z_TypeItem4 ON Item.IdTypeItem4 = Z_TypeItem4.id LEFT OUTER JOIN Z_TypeItem5 ON Item.IdTypeItem5 = Z_TypeItem5.id LEFT OUTER JOIN Z_TypeItem6 ON Item.IdTypeItem6 = Z_TypeItem6.id LEFT OUTER JOIN Z_TypeItem7 ON Item.IdTypeItem7 = Z_TypeItem7.id LEFT OUTER JOIN Z_TypeItem1 ON Item.IdTypeItem1 = Z_TypeItem1.id LEFT OUTER JOIN Z_TypeItem2 ON Item.IdTypeItem2 = Z_TypeItem2.id LEFT OUTER JOIN Z_TypeItem3 ON Item.IdTypeItem3 = Z_TypeItem3.id LEFT OUTER JOIN Z_BigUnit ON Item.IdBigUnit = Z_BigUnit.id LEFT OUTER JOIN Z_MiddellUnit ON Item.IdMiddellUnit = Z_MiddellUnit.id LEFT OUTER JOIN Z_SmallUnit ON Item.IdSmallUnit = Z_SmallUnit.id WHERE CONVERT(DATE,sal_Invoice.pdate) between @DateBegin and @DateEnd ORDER BY bill

IF @TRANS=3     SELECT  Rsal_Invoice.CostCenter,Rsal_Invoice.delegateName,  ROUND(ROUND(convert(float,RSal_Details.total_item),2) + ROUND(convert(float,RSal_Details.profit),2), 2) AS cost,ROUND((isnull(Rsal_details.qu,0)+isnull(Rsal_details.bones,0))*Item.CountMetr, 4) AS CountMetr, ROUND(convert(float,Rsal_details.total_item*Item.commission/100),2) as total_commission, Rsal_details.id_RSal AS bill, Rsal_details.id_item, ROUND(convert(float,Rsal_details.qu), 4) AS qu,ROUND(convert(float,Rsal_details.Profit), 4) AS profit, ROUND(convert(float,Rsal_details.pr),4) as pr, ROUND(convert(float,Rsal_details.Discount),4) as Discount, Rsal_details.bones, ROUND(convert(float,Rsal_details.total_item),4) as total_item, Rsal_details.unit, Item.ARname,Item.commission, Item.InternationalCode,Item.ShortName, Round(convert(float,isnull(Item.net_balance,0)),2) AS balance, Rsal_invoice.user_name,Rsal_Invoice.id_bill, Rsal_invoice.pdate, cust.Aname AS Cust_Name1,cust.way,cust.Mobile,cust.Address, Z_Stores.aname AS StoreName, Z_TypeItem1.aname AS TypeItem1, Z_TypeItem2.aname AS TypeItem2, Z_TypeItem3.aname AS TypeItem3, CASE WHEN [unit] = 0 THEN isnull(Z_BigUnit.aname, 'U-Big') WHEN [unit] = 1 THEN isnull(Z_MiddellUnit.aname, 'U-Middell') ELSE isnull(Z_SmallUnit.aname, 'U-Small') END AS UnitName, Z_TypeItem4.aname AS TypeItem4, Z_TypeItem5.aname AS TypeItem5, Z_TypeItem6.aname AS TypeItem6, Z_TypeItem7.aname AS TypeItem7,Item.Minimum, Round(convert(float,isnull(Item.net_balance,0) - isnull(Item.Minimum,0)),2) AS OverMinimum FROM         Rsal_details INNER JOIN Item ON Rsal_details.id_item = Item.id_item INNER JOIN Rsal_invoice ON Rsal_details.id_RSal = Rsal_invoice.id_Rsal INNER JOIN cust ON Rsal_invoice.id_cust = cust.id_cust left JOIN Z_Stores ON Rsal_invoice.id_store = Z_Stores.id LEFT OUTER JOIN Z_TypeItem4 ON Item.IdTypeItem4 = Z_TypeItem4.id LEFT OUTER JOIN Z_TypeItem5 ON Item.IdTypeItem5 = Z_TypeItem5.id LEFT OUTER JOIN Z_TypeItem6 ON Item.IdTypeItem6 = Z_TypeItem6.id LEFT OUTER JOIN Z_TypeItem7 ON Item.IdTypeItem7 = Z_TypeItem7.id LEFT OUTER JOIN Z_TypeItem1 ON Item.IdTypeItem1 = Z_TypeItem1.id LEFT OUTER JOIN Z_TypeItem2 ON Item.IdTypeItem2 = Z_TypeItem2.id LEFT OUTER JOIN Z_TypeItem3 ON Item.IdTypeItem3 = Z_TypeItem3.id LEFT OUTER JOIN Z_BigUnit ON Item.IdBigUnit = Z_BigUnit.id LEFT OUTER JOIN Z_MiddellUnit ON Item.IdMiddellUnit = Z_MiddellUnit.id LEFT OUTER JOIN Z_SmallUnit ON Item.IdSmallUnit = Z_SmallUnit.id WHERE CONVERT(DATE,RSAL_Invoice.pdate) between @DateBegin and @DateEnd ORDER BY bill
IF @TRANS=4     SELECT  ItemListPur.id_order as bill,  ItemListPur.id_item, ROUND(convert(float,ItemListPur.qu), 4) AS qu, ROUND(convert(float,ItemListPur.pr),4) as pr, ROUND(convert(float,ItemListPur.Discount),4) as Discount , ROUND(convert(float,ItemListPur.qu*ItemListPur.pr),4) as total_item,ItemListPur.unit, Item.ARname,Item.commission,Item.InternationalCode,Item.ShortName,Round(convert(float,isnull(Item.net_balance,0)),2) AS balance, ItemListPur.pdate, cust.Aname AS Cust_Name1,cust.way,cust.Mobile,cust.Address, Z_TypeItem1.aname AS TypeItem1, Z_TypeItem2.aname AS TypeItem2, Z_TypeItem3.aname AS TypeItem3, CASE WHEN [unit] = 0 THEN isnull(Z_BigUnit.aname, 'U-Big') WHEN [unit] = 1 THEN isnull(Z_MiddellUnit.aname, 'U-Middell') ELSE isnull(Z_SmallUnit.aname, 'U-Small') END AS UnitName, Z_TypeItem4.aname AS TypeItem4, Z_TypeItem5.aname AS TypeItem5, Z_TypeItem6.aname AS TypeItem6, Z_TypeItem7.aname AS TypeItem7,Item.Minimum, LTRIM(RTRIM(STR(isnull(CurrentBalance0,0)- isnull(Item.Minimum,0)))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS OverMinimum FROM         ItemListPur INNER JOIN Item ON ItemListPur.id_item = Item.id_item  INNER JOIN cust ON ItemListPur.id_cust = cust.id_cust  LEFT OUTER JOIN Z_TypeItem4 ON Item.IdTypeItem4 = Z_TypeItem4.id LEFT OUTER JOIN Z_TypeItem5 ON Item.IdTypeItem5 = Z_TypeItem5.id LEFT OUTER JOIN Z_TypeItem6 ON Item.IdTypeItem6 = Z_TypeItem6.id LEFT OUTER JOIN Z_TypeItem7 ON Item.IdTypeItem7 = Z_TypeItem7.id LEFT OUTER JOIN Z_TypeItem1 ON Item.IdTypeItem1 = Z_TypeItem1.id LEFT OUTER JOIN Z_TypeItem2 ON Item.IdTypeItem2 = Z_TypeItem2.id LEFT OUTER JOIN Z_TypeItem3 ON Item.IdTypeItem3 = Z_TypeItem3.id LEFT OUTER JOIN Z_BigUnit ON Item.IdBigUnit = Z_BigUnit.id LEFT OUTER JOIN Z_MiddellUnit ON Item.IdMiddellUnit = Z_MiddellUnit.id LEFT OUTER JOIN Z_SmallUnit ON Item.IdSmallUnit = Z_SmallUnit.id WHERE CONVERT(DATE,ItemListPur.pdate) between @DateBegin and @DateEnd ORDER BY bill
IF @TRANS=5     SELECT  ItemListPrice.id_order as bill,  ItemListPrice.id_item, ROUND(convert(float,ItemListPrice.qu), 4) AS qu, ROUND(convert(float,ItemListPrice.pr),4) as pr, ROUND(convert(float,ItemListPrice.Discount),4) as Discount , ROUND(convert(float,ItemListPrice.qu*ItemListPrice.pr),4) as total_item,ItemListPrice.unit, Item.ARname,Item.commission,Item.InternationalCode,Item.ShortName,Round(convert(float,isnull(Item.net_balance,0)),2) AS balance, ItemListPrice.pdate, cust.Aname AS Cust_Name1,cust.way,cust.Mobile,cust.Address, Z_TypeItem1.aname AS TypeItem1, Z_TypeItem2.aname AS TypeItem2, Z_TypeItem3.aname AS TypeItem3, CASE WHEN [unit] = 0 THEN isnull(Z_BigUnit.aname, 'U-Big') WHEN [unit] = 1 THEN isnull(Z_MiddellUnit.aname, 'U-Middell') ELSE isnull(Z_SmallUnit.aname, 'U-Small') END AS UnitName, Z_TypeItem4.aname AS TypeItem4, Z_TypeItem5.aname AS TypeItem5, Z_TypeItem6.aname AS TypeItem6, Z_TypeItem7.aname AS TypeItem7,Item.Minimum, LTRIM(RTRIM(STR(isnull(CurrentBalance0,0)- isnull(Item.Minimum,0)))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance1))) + ' ' + LTRIM(RTRIM(STR(CurrentBalance2))) AS OverMinimum FROM         ItemListPrice INNER JOIN Item ON ItemListPrice.id_item = Item.id_item  INNER JOIN cust ON ItemListPrice.id_cust = cust.id_cust  LEFT OUTER JOIN Z_TypeItem4 ON Item.IdTypeItem4 = Z_TypeItem4.id LEFT OUTER JOIN Z_TypeItem5 ON Item.IdTypeItem5 = Z_TypeItem5.id LEFT OUTER JOIN Z_TypeItem6 ON Item.IdTypeItem6 = Z_TypeItem6.id LEFT OUTER JOIN Z_TypeItem7 ON Item.IdTypeItem7 = Z_TypeItem7.id LEFT OUTER JOIN Z_TypeItem1 ON Item.IdTypeItem1 = Z_TypeItem1.id LEFT OUTER JOIN Z_TypeItem2 ON Item.IdTypeItem2 = Z_TypeItem2.id LEFT OUTER JOIN Z_TypeItem3 ON Item.IdTypeItem3 = Z_TypeItem3.id LEFT OUTER JOIN Z_BigUnit ON Item.IdBigUnit = Z_BigUnit.id LEFT OUTER JOIN Z_MiddellUnit ON Item.IdMiddellUnit = Z_MiddellUnit.id LEFT OUTER JOIN Z_SmallUnit ON Item.IdSmallUnit = Z_SmallUnit.id WHERE isnull(ItemListPrice.IsClose,0)=0 and  CONVERT(DATE,ItemListPrice.pdate) between @DateBegin and @DateEnd ORDER BY bill

end